    Bug 2012697 - Migrate filter log formatting to Fluent. r=mkmelin,coreycb


    - Migrates filterLogLine and filterMessage from filter.properties to filterEditor.ftl.
    - Refactors nsMsgFilterList::LogFilterMessage to use modern Fluent localization.
    - Optimizes string handling by utilizing UTF-8 nsAutoCString for log processing.
    - Simplifies timestamp formatting and security escaping logic.
    - Removes legacy nsIStringBundle usage in filter logging.

    Differential Revision: https://phabricator.services.mozilla.com/D280760

diff --git a/mail/locales/en-US/chrome/messenger/filter.properties b/mail/locales/en-US/chrome/messenger/filter.properties
index f1ffff4e675..d278d566e0d 100644
--- a/mail/locales/en-US/chrome/messenger/filter.properties
+++ b/mail/locales/en-US/chrome/messenger/filter.properties
@@ -44,12 +44,6 @@ filterCountVisibleOfTotal=%1$S of %2$S
 ## See: https://developer.mozilla.org/en/docs/Localization_and_Plurals
 ## #1 is the count of items in the list.
 filterCountItems=#1 item; #1 items
-# LOCALIZATION NOTE(filterLogLine):
-# %1$S=timestamp, %2$S=log message
-filterLogLine=[%1$S] %2$S
-# LOCALIZATION NOTE(filterMessage):
-# %1$S=filter name, %1$S=log message
-filterMessage=Message from filter "%1$S": %2$S
 # LOCALIZATION NOTE(filterAutoNameStr)
 # %1$S=Header or item to match, e.g. "From", "Tag", "Age in days", etc.
 # %2$S=Operator, e.g. "Contains", "is", "is greater than", etc.
diff --git a/mail/locales/en-US/messenger/filterEditor.ftl b/mail/locales/en-US/messenger/filterEditor.ftl
index 27f119c6f71..bf0ad4640f9 100644
--- a/mail/locales/en-US/messenger/filterEditor.ftl
+++ b/mail/locales/en-US/messenger/filterEditor.ftl
@@ -72,6 +72,16 @@ filter-action-log-tagged = tagged
 filter-action-log-ignore-subthread = ignored subthread
 filter-action-log-unread = marked as unread

+# Variables:
+# $timestamp (String) - The timestamp of the log entry.
+# $message (String) - The actual log message.
+filter-log-line = [{ $timestamp }] { $message }
+
+# Variables:
+# $filterName (String) - The name of the filter.
+# $message (String) - The log message from the filter.
+filter-log-message = Message from filter "{ $filterName }": { $message }
+
 filter-editor-must-select-target-folder = You must select a target folder.
 filter-editor-enter-valid-email-forward = Enter a valid email address to forward to.
 filter-editor-pick-template-reply = Choose a template to reply with.
